import generated from './font-metrics.generated.json' with { type: 'json' };
import type { Element } from './types.js';

interface FontMetrics {
  unitsPerEm: number;
  advances: Record<string, number>;
  pairs: Record<string, number>;
}
const FONT_METRICS: Record<string, FontMetrics> = generated.fonts;
export const STICKY_TEXT_INSET = 12;
export const STICKY_CORNER_RADIUS = 6;
export const TEXT_LINE_HEIGHT = 1.25;

export function resolvedFontFamily(family: string): 'Inter' | 'IBM Plex Mono' {
  return family.toLowerCase().includes('mono') ? 'IBM Plex Mono' : 'Inter';
}

/** Pure metrics generated from the exact WOFF files shipped with the app. */
export function measureTextWidth(text: string, fontSize: number, fontFamily = 'Inter'): number {
  const metrics = FONT_METRICS[resolvedFontFamily(fontFamily)]!;
  let total = 0, previous = '';
  for (const character of text.normalize('NFC')) {
    if (character === '\n' || character === '\r') { previous = ''; continue; }
    const advance = metrics.advances[character] ?? (/\p{Mark}|[\u200B-\u200D\uFE00-\uFE0F]/u.test(character) ? 0 : character === '\t' ? metrics.advances[' ']! * 4 : metrics.unitsPerEm);
    total += advance + (previous ? metrics.pairs[previous + character] ?? 0 : 0);
    previous = character;
  }
  return total * fontSize / metrics.unitsPerEm;
}

export function textSize(text: string, fontSize: number, fontFamily = 'Inter'): { w: number; h: number } {
  const lines = text.split('\n');
  return { w: Math.max(1, ...lines.map(line => measureTextWidth(line, fontSize, fontFamily))), h: Math.max(1, lines.length) * fontSize * TEXT_LINE_HEIGHT };
}

export interface TextLayoutLine {
  text: string;
  /** UTF-16 offsets into original props.text, excluding a consumed wrap separator. */
  start: number;
  end: number;
  width: number;
}
export interface TextLayout {
  /** Text sent to troika: explicit newlines, no automatic wrapping. */
  text: string;
  lines: TextLayoutLine[];
  /** Maps every UTF-16 caret boundary, including the final boundary. */
  sourceToRendered: number[];
  renderedToSource: number[];
}

function isCombining(character: string): boolean { return /\p{Mark}|[\uFE00-\uFE0F]/u.test(character); }

/** Grapheme-like boundaries independent of browser Intl/Unicode table versions. */
function nextBoundary(text: string, at: number): number {
  let end = at + (text.codePointAt(at)! > 0xffff ? 2 : 1);
  while (end < text.length) {
    const point = text.codePointAt(end)!, character = String.fromCodePoint(point);
    if (isCombining(character) || point >= 0x1f3fb && point <= 0x1f3ff) end += character.length;
    else if (point === 0x200d && end + 1 < text.length) {
      end += 1;
      end += text.codePointAt(end)! > 0xffff ? 2 : 1;
    } else break;
  }
  return end;
}

/** Explicit shared wraps plus source offsets keep SVG, troika, caret and selections aligned. */
export function textLayout(element: Element): TextLayout {
  if (element.type !== 'text' && element.type !== 'sticky') return { text: '', lines: [], sourceToRendered: [0], renderedToSource: [0] };
  const source = element.props.text;
  const inset = element.type === 'sticky' ? STICKY_TEXT_INSET : 0;
  const maxWidth = element.type === 'text' && element.props.autoSize ? Infinity : Math.max(1, element.w - inset * 2);
  const measure = (text: string) => measureTextWidth(text, element.style.fontSize, element.style.fontFamily);
  const lines: TextLayoutLine[] = [];
  let start = 0;
  while (start <= source.length) {
    const paragraphEnd = source.indexOf('\n', start);
    const end = paragraphEnd === -1 ? source.length : paragraphEnd;
    if (start === end) lines.push({ text: '', start, end, width: 0 });
    if (maxWidth === Infinity && start < end) {
      const text = source.slice(start, end);
      lines.push({ text, start, end, width: measure(text) });
      start = end;
    }
    while (start < end) {
      let cursor = start, fit = start, breakAt = -1;
      while (cursor < end) {
        const next = Math.min(end, nextBoundary(source, cursor));
        // Spaces are valid boundaries even when the space itself extends past the width.
        if (source[cursor] === ' ' || source[cursor] === '\t') breakAt = cursor;
        if (measure(source.slice(start, next)) > maxWidth && fit > start) break;
        fit = next; cursor = next;
      }
      let lineEnd = fit, nextStart = fit;
      if (fit < end && breakAt > start) { lineEnd = breakAt; nextStart = breakAt + 1; }
      const text = source.slice(start, lineEnd);
      lines.push({ text, start, end: lineEnd, width: measure(text) });
      start = nextStart;
    }
    if (paragraphEnd === -1) break;
    start = paragraphEnd + 1;
  }

  const sourceToRendered = new Array<number>(source.length + 1);
  const renderedToSource: number[] = [0];
  let rendered = '';
  for (let index = 0; index < lines.length; index++) {
    const line = lines[index]!;
    const renderedStart = rendered.length;
    // At an inserted wrap boundary choose the beginning of the next line for a source caret.
    for (let i = line.start; i <= line.end; i++) {
      sourceToRendered[i] = renderedStart + i - line.start;
      renderedToSource[renderedStart + i - line.start] = i;
    }
    rendered += line.text;
    if (index < lines.length - 1) {
      const nextStart = lines[index + 1]!.start;
      for (let i = line.end + 1; i < nextStart; i++) sourceToRendered[i] = rendered.length;
      renderedToSource[rendered.length] = line.end;
      rendered += '\n';
      renderedToSource[rendered.length] = nextStart;
    }
  }
  sourceToRendered[source.length] = rendered.length;
  renderedToSource[rendered.length] = source.length;
  return { text: rendered, lines, sourceToRendered, renderedToSource };
}

export function textLines(element: Element): string[] { return textLayout(element).lines.map(line => line.text); }

packages/model/src/types.ts.source:
export type ElementType = 'rect' | 'ellipse' | 'sticky' | 'text' | 'stroke' | 'connector' | 'image';
export interface Point { x: number; y: number }
export interface Box extends Point { w: number; h: number }
export interface ElementStyle {
  stroke: string;
  fill: string;
  strokeWidth: number;
  opacity: number;
  fontFamily: string;
  fontSize: number;
  color: string;
}
export type Binding = Point | { elementId: string; nx: number; ny: number; fallback: Point };
export interface TextProps { text: string; align: 'left' | 'center' | 'right'; autoSize: boolean }
export interface StrokeProps { points: number[]; simplified: boolean }
export interface ConnectorProps { start: Binding; end: Binding; kind: 'straight' | 'elbow' | 'curve' }
export interface ImageProps { assetId: string; naturalW: number; naturalH: number }
export interface PropsByType {
  rect: Record<string, never>;
  ellipse: Record<string, never>;
  sticky: TextProps;
  text: TextProps;
  stroke: StrokeProps;
  connector: ConnectorProps;
  image: ImageProps;
}
export type ElementOf<T extends ElementType> = Box & {
  id: string;
  type: T;
  rotation: number;
  index: string;
  style: ElementStyle;
  props: PropsByType[T];
};
export type Element = { [T in ElementType]: ElementOf<T> }[ElementType];
export type ElementPatch<T extends ElementType = ElementType> = Partial<Box & {
  rotation: number;
  index: string;
  style: ElementStyle;
  props: PropsByType[T];
}>;
export type ElementInput<T extends ElementType> = Partial<Box & {
  id: string;
  rotation: number;
  index: string;
  style: Partial<ElementStyle>;
  props: PropsByType[T];
}>;

export const DEFAULT_STYLE: Readonly<ElementStyle> = Object.freeze({
  stroke: '#334155', fill: '#ffffff', strokeWidth: 2, opacity: 1,
  fontFamily: 'Inter', fontSize: 24, color: '#172033',
});
